/**
 * @description Preview payload (admins) and View request (anyone who can see the transaction). previewPayload shows the
 * request a send would make for one record, built by the same code as a real send, or the call the middleware must
 * make for an inbound event; nothing is sent and nothing is saved. getExchange shows what was sent and received for one
 * transaction (built by IntegrationHubExchange).
 * @group Integration Hub
 */
public with sharing class IntegrationHubPreview {

    /** @description Transaction Id shown in a preview body. */
    public static final String PREVIEW_ID = 'PREVIEW';
    /** @description Start of the inbound and callback URLs. */
    public static final String REST_BASE = '/services/apexrest/integrationhub/v1/';

    /**
     * @description One request header.
     */
    public class Header {
        /** @description Header name. */
        @AuraEnabled
        public String name;
        /** @description Header value. */
        @AuraEnabled
        public String value;

        /**
         * @description A header.
         * @param headerName the name
         * @param headerValue the value
         */
        public Header(String headerName, String headerValue) {
            name = headerName;
            value = headerValue;
        }
    }

    /**
     * @description The request of an event for one record, and what comes back.
     */
    public class Preview {
        /** @description Event key. */
        @AuraEnabled
        public String eventKey;
        /** @description Outbound or Inbound. */
        @AuraEnabled
        public String direction;
        /** @description Connection name. */
        @AuraEnabled
        public String connectionName;
        /** @description The record used, e.g. "Case 00001026". */
        @AuraEnabled
        public String recordLabel;
        /** @description HTTP method. */
        @AuraEnabled
        public String method;
        /** @description Outbound: callout:<Named Credential><path>. Inbound: the REST path. */
        @AuraEnabled
        public String url;
        /** @description Request headers. */
        @AuraEnabled
        public List<Header> headers = new List<Header>();
        /** @description Pretty-printed JSON body; null when there is a problem. */
        @AuraEnabled
        public String body;
        /** @description Selected Fields, Apex Class: <name>, or Sample from <object> <record> (inbound). */
        @AuraEnabled
        public String bodySource;
        /** @description True when the event expects a callback. */
        @AuraEnabled
        public Boolean expectsCallback = false;
        /** @description Hours the callback may take. */
        @AuraEnabled
        public Integer callbackHours;
        /** @description Callback URL with the transaction Id placeholder. */
        @AuraEnabled
        public String callbackUrl;
        /** @description Sample callback body. */
        @AuraEnabled
        public String callbackBody;
        /** @description The event's Business Data In Response option. */
        @AuraEnabled
        public Boolean businessData = false;
        /** @description A problem in plain words (record not found, class error); null when the body was built. */
        @AuraEnabled
        public String message;
    }

    /**
     * @description What was sent and received for one transaction. The screen reads these members by name, so they
     * stay flat in one class.
     */
    @SuppressWarnings('PMD.ExcessivePublicCount, PMD.TooManyFields')
    public class Exchange {
        /** @description Transaction Id. */
        @AuraEnabled
        public Id transactionId;
        /** @description Transaction Number. */
        @AuraEnabled
        public String name;
        /** @description Event key. */
        @AuraEnabled
        public String eventKey;
        /** @description Outbound or Inbound. */
        @AuraEnabled
        public String direction;
        /** @description Delivery status. */
        @AuraEnabled
        public String status;
        /** @description Connection name. */
        @AuraEnabled
        public String connectionName;
        /** @description Last send (outbound) or when the call came in (inbound). */
        @AuraEnabled
        public Datetime sentAt;
        /** @description Method and URL of the request. */
        @AuraEnabled
        public String requestUrl;
        /** @description Request headers (values as sent where they are stored). */
        @AuraEnabled
        public List<Header> requestHeaders = new List<Header>();
        /** @description Request body (outbound: what was sent; inbound: what the middleware sent). */
        @AuraEnabled
        public String requestBody;
        /** @description True when the stored request body was cut. */
        @AuraEnabled
        public Boolean requestCut = false;
        /** @description File (ContentDocument) with the full request body, when one exists. */
        @AuraEnabled
        public Id requestFileId;
        /** @description HTTP status of the answer. */
        @AuraEnabled
        public Integer httpStatus;
        /** @description Answer body (outbound: the middleware's answer; inbound: what Salesforce answered). */
        @AuraEnabled
        public String responseBody;
        /** @description True when the stored answer was cut. */
        @AuraEnabled
        public Boolean responseCut = false;
        /** @description File (ContentDocument) with the full answer. */
        @AuraEnabled
        public Id responseFileId;
        /** @description True when the event expects a callback. */
        @AuraEnabled
        public Boolean expectsCallback = false;
        /** @description Callback body received. */
        @AuraEnabled
        public String callbackBody;
        /** @description True when the stored callback body was cut. */
        @AuraEnabled
        public Boolean callbackCut = false;
        /** @description File (ContentDocument) with the full callback body. */
        @AuraEnabled
        public Id callbackFileId;
        /** @description True when the event has Business Data In Response or the transaction has a Business Status. */
        @AuraEnabled
        public Boolean businessData = false;
        /** @description Response Handler Class of the event. */
        @AuraEnabled
        public String handlerClass;
        /** @description Business Status: Processing, Done or Failed. */
        @AuraEnabled
        public String businessStatus;
        /** @description The line the handler set. */
        @AuraEnabled
        public String businessResult;
        /** @description Why the handler failed. */
        @AuraEnabled
        public String businessError;
        /** @description How many times the handler ran in the background. */
        @AuraEnabled
        public Integer businessRuns;
        /** @description True when the user is an admin and Business Status is Failed. */
        @AuraEnabled
        public Boolean canRerun = false;
        /** @description Sends and handler reruns, oldest first. */
        @AuraEnabled
        public List<AttemptRow> attempts = new List<AttemptRow>();
        /** @description Failed and waiting for auto-retry: when the send runs again; null when none is planned. */
        @AuraEnabled
        public Datetime nextRetryAt;
        /** @description Automatic retries already made. */
        @AuraEnabled
        public Integer autoRetries = 0;
        /** @description The event's Auto Retry Max (0: off). */
        @AuraEnabled
        public Integer autoRetryMax = 0;
    }

    /**
     * @description One Integration Attempt.
     */
    public class AttemptRow {
        /** @description Position, from 1. */
        @AuraEnabled
        public Integer n;
        /** @description When. */
        @AuraEnabled
        public Datetime at;
        /** @description Send, Auto Retry or Handler Rerun. */
        @AuraEnabled
        public String kind;
        /** @description HTTP status; null for a rerun or when no answer came. */
        @AuraEnabled
        public Integer httpStatus;
        /** @description Result. */
        @AuraEnabled
        public String outcome;
        /** @description New or Original payload. */
        @AuraEnabled
        public String payloadUsed;
        /** @description Error summary. */
        @AuraEnabled
        public String error;
    }

    /**
     * @description Builds the request of an event for one record without sending or saving anything. Admins only.
     * @param eventId the event
     * @param recordInput a record Id, or the value of the object's name field (e.g. Case Number); may be blank for an
     * inbound event
     * @return the preview; message says what went wrong
     */
    @AuraEnabled
    public static Preview previewPayload(Id eventId, String recordInput) {
        IntegrationHubMonitorController.requireAdmin();
        IH_Event__c ev = eventId == null ? null : (IH_Event__c) IntegrationHubData.queryFirst(
            'SELECT Id, Name, Event_Key__c, Direction__c, Active__c, Related_Object__c, Connection__c, Connection__r.Name, '
            + 'Connection__r.Named_Credential__c, Connection__r.Headers__c, Connection__r.Connection_Type__c, '
            + 'Connection__r.Auth_Class__c, Path__c, Http_Method__c, Payload_Fields__c, '
            + 'Payload_Source__c, Payload_Class__c, Transaction_Id_Key__c, Expects_Callback__c, Callback_Timeout_Hours__c, '
            + 'Response_Handler_Class__c, Business_Data_In_Response__c, Handler_Class__c FROM IH_Event__c WHERE Id = :id LIMIT 1',
            new Map<String, Object>{ 'id' => eventId });
        Preview p = new Preview();
        if (ev == null) {
            p.message = 'Event not found.';
            return p;
        }
        p.eventKey = ev.Event_Key__c;
        p.direction = ev.Direction__c;
        p.connectionName = ev.Connection__r?.Name;
        p.businessData = ev.Business_Data_In_Response__c == true;
        String input = recordInput == null ? '' : recordInput.trim();
        if (ev.Direction__c == IntegrationHub.INBOUND) {
            IntegrationHubPreviewSample.inbound(p, ev, input);
        } else {
            outbound(p, ev, input);
        }
        return p;
    }

    /**
     * @description What was sent and received for one transaction. Anyone who can see the transaction may open it;
     * Rerun is offered to admins only.
     * @param transactionId the transaction
     * @return the exchange
     */
    @AuraEnabled
    public static Exchange getExchange(Id transactionId) {
        List<IH_Transaction__c> visible = transactionId == null ? new List<IH_Transaction__c>()
            : [SELECT Id FROM IH_Transaction__c WHERE Id = :transactionId WITH USER_MODE LIMIT 1];
        if (visible.isEmpty()) {
            throw auraError('You cannot open this transaction.');
        }
        return IntegrationHubExchange.build(transactionId);
    }

    /**
     * @description True when the user has the Integration Hub Admin permission.
     * @return whether the user is an admin
     */
    public static Boolean isAdmin() {
        try {
            IntegrationHubMonitorController.requireAdmin();
            return true;
        } catch (AuraHandledException e) {
            return false;
        }
    }

    /**
     * @description An error the screen shows as it is.
     * @param message the text
     * @return the exception
     */
    public static AuraHandledException auraError(String message) {
        AuraHandledException e = new AuraHandledException(message);
        e.setMessage(message);
        return e;
    }

    /**
     * @description The headers a send uses: Content-Type, X-Correlation-Id and the connection headers over them. Values
     * of secret headers (authorization, token, secret, password, api-key...) are masked, e.g. "Bearer ••••".
     * @param correlationId the X-Correlation-Id value
     * @param headersJson the connection headers (JSON object, may be blank or invalid)
     * @return the headers, safe to show
     */
    public static List<Header> sendHeaders(String correlationId, String headersJson) {
        List<Header> headers = new List<Header>{ new Header('Content-Type', 'application/json') };
        if (String.isNotBlank(correlationId)) {
            headers.add(new Header('X-Correlation-Id', correlationId));
        }
        Map<String, Object> extra = IntegrationHubInbound.parseObject(headersJson);
        for (String headerName : extra == null ? new List<String>() : new List<String>(extra.keySet())) {
            Object value = extra.get(headerName);
            setHeader(headers, headerName, IntegrationHubHeaderMask.maskValue(headerName, value == null ? '' : String.valueOf(value)));
        }
        return headers;
    }

    /**
     * @description The headers a send through this connection uses, masked as in sendHeaders(String, String). For an
     * Apex Auth connection the Authorization line says that the Auth Class adds it at send time; it is never shown.
     * @param correlationId the X-Correlation-Id value
     * @param conn the connection (Headers__c, Connection_Type__c and Auth_Class__c read; may be null)
     * @return the headers, safe to show
     */
    public static List<Header> sendHeaders(String correlationId, IH_Connection__c conn) {
        List<Header> headers = sendHeaders(correlationId, conn?.Headers__c);
        if (IntegrationHubConnectionAuth.isApexAuth(conn)) {
            setHeader(headers, 'Authorization', IntegrationHubConnectionAuth.hiddenLine(conn));
        }
        return headers;
    }

    private static void setHeader(List<Header> headers, String headerName, String value) {
        for (Header h : headers) {
            if (h.name.equalsIgnoreCase(headerName)) {
                h.value = value;
                return;
            }
        }
        headers.add(new Header(headerName, value));
    }

    private static void outbound(Preview p, IH_Event__c ev, String input) {
        p.bodySource = ev.Payload_Source__c == IntegrationHubPayload.SOURCE_APEX ? 'Apex Class: ' + ev.Payload_Class__c : 'Selected Fields';
        String txnKey = IntegrationHubPayload.txnKeyOf(ev);
        callback(p, ev, txnKey);
        SObject rec = IntegrationHubPreviewSample.findRecord(IntegrationHubPreviewSample.describe(ev.Related_Object__c), input);
        IntegrationHubCallout.RequestSpec spec = new IntegrationHubCallout.RequestSpec();
        String credential = ev.Connection__r?.Named_Credential__c;
        spec.namedCredential = String.isBlank(credential) ? '<no Named Credential>' : credential;
        spec.path = ev.Path__c;
        spec.method = ev.Http_Method__c;
        spec.timeoutMs = 10000;
        spec.recordId = rec == null ? '{recordId}' : String.valueOf(rec.Id);
        spec.transactionId = PREVIEW_ID;
        HttpRequest req = IntegrationHubCallout.buildRequest(spec);
        p.method = req.getMethod();
        p.url = req.getEndpoint();
        p.headers = sendHeaders('(new per send)', ev.Connection__r);
        if (rec == null) {
            p.message = notFound(ev.Related_Object__c, input);
            return;
        }
        p.recordLabel = IntegrationHubPreviewSample.labelOf(rec);
        IH_Transaction__c txn = new IH_Transaction__c(Event__c = ev.Id, Event_Name__c = ev.Event_Key__c,
            Direction__c = IntegrationHub.OUTBOUND, Related_Record_Id__c = rec.Id, Related_Object__c = String.valueOf(rec.getSObjectType()));
        IntegrationHubPayload.Result built = IntegrationHubPayload.build(ev, new List<IH_Transaction__c>{ txn });
        p.message = built.errors.get(null);
        p.body = p.message == null ? previewBody(built.bodies.get(null), txnKey, ev.Payload_Source__c != IntegrationHubPayload.SOURCE_APEX) : null;
    }

    /**
     * @description The built body with PREVIEW as the transaction Id, pretty-printed. Selected Fields bodies get the key
     * first (it was left out because the preview has no Id); class bodies get it where they carry it.
     * @param body the body as built
     * @param txnKey the transaction Id key
     * @param addKey true for Selected Fields
     * @return the pretty body
     */
    @TestVisible
    private static String previewBody(String body, String txnKey, Boolean addKey) {
        Map<String, Object> parsed = IntegrationHubInbound.parseObject(body);
        if (parsed == null) {
            return body;
        }
        Map<String, Object> out = parsed;
        if (parsed.containsKey(txnKey)) {
            parsed.put(txnKey, PREVIEW_ID);
        } else if (addKey) {
            out = new Map<String, Object>{ txnKey => PREVIEW_ID };
            out.putAll(parsed);
        }
        return JSON.serializePretty(out);
    }

    private static void callback(Preview p, IH_Event__c ev, String txnKey) {
        p.expectsCallback = ev.Expects_Callback__c == true;
        if (p.expectsCallback) {
            p.callbackHours = ev.Callback_Timeout_Hours__c == null ? 24 : ev.Callback_Timeout_Hours__c.intValue();
            p.callbackUrl = REST_BASE + 'callback/{' + txnKey + '}';
            p.callbackBody = sampleCallback(p.businessData);
        }
    }

    private static String notFound(String objectName, String input) {
        if (String.isBlank(input)) {
            return 'Enter a record Id or its name.';
        }
        return 'No ' + objectName + ' record found for "' + input + '".';
    }

    private static String sampleCallback(Boolean businessData) {
        Map<String, Object> sample = new Map<String, Object>{ 'status' => 'SUCCESS', 'reference' => 'THEIR-REF-123', 'message' => 'Done' };
        if (businessData) {
            sample.put('data', new Map<String, Object>{ 'anyField' => 'any JSON your Response Handler Class reads' });
        }
        return JSON.serializePretty(sample);
    }
}
